1	const PROCESSING_FEE = 5;
2	const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
3	const BLOCK_SIZE = 3;
4	const BLOCK_DISCOUNT_PERCENT = 20;
5	const CURSE_SURCHARGE_PERCENT = 50;
6	const HIGH_ENCHANTMENT_THRESHOLD = 5;
7	const HIGH_ENCHANTMENT_SURCHARGE_PERCENT = 30;
8	const LOYALTY_YEARS_THRESHOLD = 2;
9	const LOYALTY_DISCOUNT_PERCENT = 20;
10	const FOLLOW_UP_DISCOUNT_PERCENT = 15;
11	
12	const BASE_PREMIUMS = {
13	  sword: 100,
14	  amulet: 60,
15	  staff: 80,
16	  potion: 40,
17	  rune: 25,
18	  moonstone: 25,
19	} as const;
20	
21	// The six priced types are the domain, so they are derived from the premium
22	// table rather than restated: a type nobody prices cannot be insured. The
23	// unknown-type case (broomstick) is still a runtime error the tests will drive.
24	type ItemType = keyof typeof BASE_PREMIUMS;
25	
26	// Components (as opposed to main items) are the only things the block rule
27	// applies to, so the distinction has to be data, not a price coincidence.
28	// Typed as a set of ItemType so a component can never name an unpriced type.
29	const COMPONENT_TYPES = new Set<ItemType>(["rune", "moonstone"]);
30	
31	const PERCENT_WHOLE = 100;
32	
33	// Divides rather than multiplying by a rate: `amount * 1.1` introduces
34	// floating-point error that shifts the spec's round-up in MHPCO's favour.
35	const percentOf = (percent: number, amount: number): number =>
36	  (amount * percent) / PERCENT_WHOLE;
37	
38	// MHPCO rounds every money amount in its own favour: premiums (customer pays)
39	// round up, payouts (MHPCO pays) round down.
40	const roundPremiumInMHPCOsFavour = Math.ceil;
41	
42	export type ScenarioResult = { premium: number };
43	
44	// Items carry attributes no rule reads yet (material/enchantment/cursed drive
45	// the surcharge and claim tests still to come). They are typed as optional so
46	// the scenarios the tests actually send typecheck, without pricing them.
47	type Item = {
48	  type: ItemType;
49	  material?: string;
50	  enchantment?: number;
51	  cursed?: boolean;
52	};
53	
54	type Step = { op: string; items: Item[] };
55	
56	type Customer = { yearsWithMHPCO: number };
57	
58	// `op` is still unread: the claim tests will reach for it.
59	type Scenario = {
60	  customer: Customer;
61	  steps: Step[];
62	};
63	
64	const sum = (amounts: number[]): number =>
65	  amounts.reduce((total, amount) => total + amount, 0);
66	
67	const basePremiumForItem = (item: Item): number => BASE_PREMIUMS[item.type];
68	
69	const sumBasePremiums = (items: Item[]): number => sum(items.map(basePremiumForItem));
70	
71	// Groups of items that are "alike" — same type. The type is kept alongside the
72	// items because the block rule asks about it; recovering it from items[0] would
73	// make every reader re-derive that a group is non-empty and homogeneous.
74	type AlikeItems = { type: ItemType; items: Item[] };
75	
76	const groupByType = (items: Item[]): AlikeItems[] => {
77	  const groups = new Map<ItemType, Item[]>();
78	  for (const item of items) {
79	    const group = groups.get(item.type) ?? [];
80	    group.push(item);
81	    groups.set(item.type, group);
82	  }
83	  return [...groups].map(([type, groupedItems]) => ({ type, items: groupedItems }));
84	};
85	
86	// A block is a discount on the components' combined base premium, not a flat
87	// price: 3 runes are 75 G less 20 % = 60 G. Derived rather than hardcoded so the
88	// 20 % stays visible as the rule it is.
89	const blockBasePremium = (items: Item[]): number => {
90	  const undiscounted = sumBasePremiums(items);
91	  return undiscounted - percentOf(BLOCK_DISCOUNT_PERCENT, undiscounted);
92	};
93	
94	// Exactly BLOCK_SIZE, not "at least": 4 or 7 runes form no block, so a bigger
95	// pile is never cheaper than the block it contains. Components only — three
96	// swords are three separate insurances, not a discounted building block.
97	const formsABlock = ({ type, items }: AlikeItems): boolean =>
98	  items.length === BLOCK_SIZE && COMPONENT_TYPES.has(type);
99	
100	const basePremiumForGroup = (alikeItems: AlikeItems): number =>
101	  formsABlock(alikeItems)
102	    ? blockBasePremium(alikeItems.items)
103	    : sumBasePremiums(alikeItems.items);
104	
105	// Priced per group of alike items rather than over the whole list, so 3 runes
106	// and 3 moonstones each form their own block.
107	const policyBasePremiumFor = (items: Item[]): number =>
108	  sum(groupByType(items).map(basePremiumForGroup));
109	
110	const percentOfWhen = (applies: boolean, percent: number, amount: number): number =>
111	  applies ? percentOf(percent, amount) : 0;
112	
113	// Each item-specific surcharge is a percentage of the affected item's OWN base
114	// premium, so every rule reads as "this much, when this holds". The terms are
115	// summed rather than chosen between: an item can trigger several at once.
116	//
117	// Deliberately two explicit terms rather than a table of rules. The shared
118	// shape is only the arithmetic tail; the conditions differ in kind (a flag vs.
119	// a threshold over an optional number), and nothing in the remaining spec adds
120	// a third item-specific surcharge to generalise over.
121	const surchargeFor = (item: Item): number => {
122	  const base = basePremiumForItem(item);
123	  return (
124	    percentOfWhen(item.cursed === true, CURSE_SURCHARGE_PERCENT, base) +
125	    percentOfWhen(
126	      (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD,
127	      HIGH_ENCHANTMENT_SURCHARGE_PERCENT,
128	      base,
129	    )
130	  );
131	};
132	
133	// Charged alongside the policy base premium — never folded into it, or the
134	// policy-wide modifiers would compound on top of them.
135	const itemSurchargesFor = (items: Item[]): number => sum(items.map(surchargeFor));
136	
137	// Unlike the item-specific surcharges, these are percentages of the WHOLE
138	// policy's base premium. Each is returned already signed — a surcharge is
139	// positive, a discount negative — so the rule and its direction stay on one
140	// line instead of the sign living in a `+`/`-` further down the sum.
141	const policyModifiersFor = (
142	  policyBasePremium: number,
143	  customer: Customer,
144	  isFollowUpContract: boolean,
145	): number[] => [
146	  // Applies to every quote, follow-ups included: the spec treats each item in a
147	  // quote as newly insured, regardless of how long the customer has been around.
148	  percentOf(FIRST_INSURANCE_SURCHARGE_PERCENT, policyBasePremium),
149	  -percentOfWhen(
150	    customer.yearsWithMHPCO >= LOYALTY_YEARS_THRESHOLD,
151	    LOYALTY_DISCOUNT_PERCENT,
152	    policyBasePremium,
153	  ),
154	  -percentOfWhen(isFollowUpContract, FOLLOW_UP_DISCOUNT_PERCENT, policyBasePremium),
155	];
156	
157	// The order of the terms is the order of the spec's rules: what the items are
158	// worth, what they individually cost extra, what the policy as a whole is
159	// adjusted by, and MHPCO's fee on top.
160	const quoteFor = (
161	  items: Item[],
162	  customer: Customer,
163	  isFollowUpContract: boolean,
164	): ScenarioResult => {
165	  const policyBasePremium = policyBasePremiumFor(items);
166	  const premium = roundPremiumInMHPCOsFavour(
167	    policyBasePremium +
168	      itemSurchargesFor(items) +
169	      sum(policyModifiersFor(policyBasePremium, customer, isFollowUpContract)) +
170	      PROCESSING_FEE,
171	  );
172	  return { premium };
173	};
174	
175	// Every step is a quote so far, so a step's position is also its contract
176	// number: the first is the customer's first contract, the rest are follow-ups.
177	export const runScenario = (scenario: Scenario): { results: ScenarioResult[] } => {
178	  const results = scenario.steps.map((step, index) =>
179	    quoteFor(step.items, scenario.customer, index > 0),
180	  );
181	  return { results };
182	};
