// Every step is a quote so far, so a step's position is also its contract
// number: the first is the customer's first contract, the rest are follow-ups.
export const runScenario = (scenario: Scenario): { results: ScenarioResult[] } => {
  const results = scenario.steps.map((step, index) =>
    quoteFor(step.items, scenario.customer, index > 0),
  );
  return { results };
};

