// A follow-up contract is any quote after the customer's first. Every step is a
// quote so far, so a step's position stands in for the number of quotes before
// it. That equivalence is this function and nothing else — once claim steps
// exist, a claim at index 0 would wrongly make a quote at index 1 a follow-up,
// and the fix is to count preceding QUOTE steps here.
const isFollowUpContract = (stepIndex: number): boolean => stepIndex > 0;

export const runScenario = (scenario: Scenario): { results: ScenarioResult[] } => {
  const results = scenario.steps.map((step, stepIndex) =>
    quoteFor(step.items, scenario.customer, isFollowUpContract(stepIndex)),
  );
  return { results };
};
